using System;using System.IO;using System.Drawing;using System.Drawing.Printing;using System.Reflection;using System.Diagnostics;using System.Windows.Forms;using EanEtikety;
class PrintPreviewTests {
 static int checks;static string dir;static readonly BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool value,string message){checks++;if(!value)throw new Exception(message);}
 static T F<T>(object o,string n){return (T)o.GetType().GetField(n,Hidden).GetValue(o);}static void Set(object o,string n,object v){o.GetType().GetField(n,Hidden).SetValue(o,v);}static object Call(object o,string n,params object[] a){foreach(var method in o.GetType().GetMethods(Hidden))if(method.Name==n&&method.GetParameters().Length==a.Length)return method.Invoke(o,a);throw new MissingMethodException(n);}
 static void Pump(Func<bool> done){var s=Stopwatch.StartNew();while(!done()){Application.DoEvents();System.Threading.Thread.Sleep(1);if(s.ElapsedMilliseconds>30000)throw new Exception("preview timeout");}}
 static void Wait(PrintPanel p,Action action){int before=p.PreviewBuilds;action();Pump(()=>p.PreviewBuilds!=before);Check(p.Ready,"valid preview remains ready");}
 static Form Host(PrintPanel p){Set(p,"initialPrinterName","Microsoft Print to PDF");var f=new Form{Size=new Size(1050,760),StartPosition=FormStartPosition.Manual,Location=new Point(-20000,-20000)};f.Controls.Add(p);Wait(p,()=>f.Show());return f;}
 static bool ImagesEqual(Image a,Image b){using(var x=new Bitmap(512,512))using(var y=new Bitmap(512,512)){using(var g=Graphics.FromImage(x)){g.Clear(Color.White);g.DrawImage(a,new Rectangle(0,0,512,512));}using(var g=Graphics.FromImage(y)){g.Clear(Color.White);g.DrawImage(b,new Rectangle(0,0,512,512));}for(int row=0;row<512;row++)for(int col=0;col<512;col++)if(x.GetPixel(col,row)!=y.GetPixel(col,row))return false;return true;}}
 static void Reuse(){using(var p=new PrintPanel(LabelSettings.Default()))using(var f=Host(p)){
  Wait(p,()=>p.RefreshPreview());Check(p.LastPreviewPerformance.ArtworkCacheHit,"unchanged preview reuses artwork");Check(p.LastPreviewPerformance.DriverGeometryReads==0&&p.LastPreviewPerformance.RenderedPages==0,"unchanged preview avoids repeated native geometry and rendering");
  var first=F<PreflightReport>(p,"currentReport");Wait(p,()=>F<NumericUpDown>(p,"offsetX").Value=1);Check(!p.LastPreviewPerformance.ArtworkCacheHit&&p.LastPreviewPerformance.RenderedPages==1,"new calibration renders fresh artwork");Check(first.Fingerprint!=F<PreflightReport>(p,"currentReport").Fingerprint,"reuse cannot hide changed print approval");Wait(p,()=>F<NumericUpDown>(p,"offsetX").Value=0);Check(p.LastPreviewPerformance.ArtworkCacheHit,"returning to a cached correction reuses its independent image");
  var cache=F<object>(p,"previewCache");for(int i=1;i<=7;i++)Wait(p,()=>F<NumericUpDown>(p,"offsetX").Value=i);Check((int)cache.GetType().GetProperty("ImageCount").GetValue(cache,null)<=4,"artwork cache entry count is bounded");Check((long)cache.GetType().GetProperty("ImageBytes").GetValue(cache,null)<=32L*1024*1024,"artwork cache byte count is bounded");
  Wait(p,()=>Call(p,"StartRequest",true,false,null));Check(p.LastPreviewPerformance.DriverGeometryReads==3&&p.LastPreviewPerformance.CapabilityReads>0&&!p.LastPreviewPerformance.ArtworkCacheHit,"printer refresh reloads facts and capabilities");
  Wait(p,()=>Check(p.ConfigurePrinter(dialog=>DialogResult.OK),"accept unchanged named driver setup"));Check(p.LastPreviewPerformance.DriverGeometryReads==3&&!p.LastPreviewPerformance.ArtworkCacheHit,"accepting driver properties invalidates opaque DEVMODE even when named dimensions match");
  using(var d=new LabelPrintDocument(F<LabelSettings>(p,"snapshot"),F<OutputPlan>(p,"outputPlan"))){d.OffsetX=(double)F<NumericUpDown>(p,"offsetX").Value;var canvas=F<PrintCanvas>(p,"preview");using(var uncached=d.CreatePreview(0,canvas.Paper))Check(ImagesEqual(F<Image>(canvas,"image"),uncached),"cached and uncached vector artwork rasterize identically");}
  f.Close();Check((int)cache.GetType().GetProperty("ImageCount").GetValue(cache,null)==0,"closing window disposes all cached artwork");
 }}
 static void FreshSubmit(){using(var p=new PrintPanel(LabelSettings.Default()))using(var f=Host(p)){Wait(p,()=>p.RefreshPreview());Check(p.LastPreviewPerformance.ArtworkCacheHit,"submit fixture has warmed artwork");var report=F<PreflightReport>(p,"currentReport");Set(p,"approvedFingerprint",report.Fingerprint);var original=F<Func<PageSettings,PrinterPageGeometry>>(p,"geometryReader");int reads=0;Set(p,"geometryReader",(Func<PageSettings,PrinterPageGeometry>)(page=>{reads++;var g=original(page);return new PrinterPageGeometry(g.Bounds,g.PrintableArea,g.HardMarginX+1,g.HardMarginY,g.Landscape);}));int builds=p.PreviewBuilds;Call(p,"StartRequest",false,true,null);Pump(()=>!F<bool>(p,"busy"));Check(reads==1&&p.PreviewBuilds==builds,"submit refreshes driver facts rather than trusting cached preview");Check(F<PreflightReport>(p,"currentReport").Fingerprint!=report.Fingerprint&&F<Label>(p,"info").Text.Contains("znova"),"changed hard margin invalidates approval before any print job");f.Close();}}
 static void OwnedPlans(){var label=LabelSettings.Default();label.Variables.Add(new VariableField{Name="serial",Start=1,Digits=3});label.Ean="{serial}";label.Kind=128;using(var p=new PrintPanel(label))using(var f=Host(p)){Wait(p,()=>p.RefreshPreview());Check(p.LastPreviewPerformance.ArtworkCacheHit,"prepared variable job can reuse frozen artwork");Set(p,"jobClock",(Func<DateTime>)(()=>new DateTime(2030,1,1)));Wait(p,()=>Call(p,"RefreshJobVariables"));Check(!p.LastPreviewPerformance.ArtworkCacheHit&&p.LastPreviewPerformance.RenderedPages==1,"recalculation invalidates previous plan artwork");f.Close();}
  var plain=LabelSettings.Default();var plan=OutputPlan.Create(plain);using(var p=new PrintPanel(plain,plan))using(var f=Host(p)){using(var previous=(Image)F<Image>(F<PrintCanvas>(p,"preview"),"image").Clone()){plan.Placements[0].Label.Texts[0].Text="B";Wait(p,()=>p.RefreshPreview());Check(!p.LastPreviewPerformance.ArtworkCacheHit&&!ImagesEqual(previous,F<Image>(F<PrintCanvas>(p,"preview"),"image")),"externally mutable plans always render current data");}f.Close();}
 }
 static void Ownership(){var type=typeof(PrintPanel).Assembly.GetType("EanEtikety.PreviewSessionCache",true);var cache=Activator.CreateInstance(type,true);using(var source=new Bitmap(20,20)){Call(cache,"StoreImage","test",source);}using(var a=(Image)Call(cache,"GetImage","test"))using(var b=(Image)Call(cache,"GetImage","test")){Check(a!=null&&b!=null&&!ReferenceEquals(a,b),"each cache result has independent native ownership");a.Dispose();Check(b.Width==20,"disposing one delivered image cannot break another");}
  var geometry=new PrinterPageGeometry(new Rectangle(0,0,827,1169),new RectangleF(0,0,827,1169),0,0,false);Call(cache,"StoreGeometry","g",geometry,10.0);Check(ReferenceEquals(Call(cache,"GetGeometry","g",5009.0),geometry)&&Call(cache,"GetGeometry","g",5010.0)==null&&Call(cache,"GetGeometry","g",9.0)==null,"geometry expires after five seconds and rejects backwards time");
  using(var large=new Bitmap(3000,3000))Call(cache,"StoreImage","over-budget",large);Check(Call(cache,"GetImage","over-budget")==null,"oversized cache entry is declined before cloning");((IDisposable)cache).Dispose();using(var b=new Bitmap(20,20))Call(cache,"StoreImage","late",b);Check(Call(cache,"GetImage","late")==null&&(int)type.GetProperty("ImageCount").GetValue(cache,null)==0,"late worker result cannot repopulate disposed cache");
 }
 static void CacheFailures(){var cache=Activator.CreateInstance(typeof(PrintPanel).Assembly.GetType("EanEtikety.PreviewSessionCache",true),true);using(var source=new Bitmap(20,20)){Call(cache,"StoreImage","valid",source);Set(cache,"cloneImage",(Func<Image,Image>)(image=>{throw new OutOfMemoryException("simulated cache allocation failure");}));Check(Call(cache,"GetImage","valid")==null,"cache clone allocation failure falls back to fresh rendering");Call(cache,"StoreImage","uncached",source);Check(source.Width==20,"failed cache storage preserves successfully rendered source");}((IDisposable)cache).Dispose();}
 static void Responsiveness(){using(var entered=new System.Threading.ManualResetEvent(false))using(var release=new System.Threading.ManualResetEvent(false))using(var p=new PrintPanel(LabelSettings.Default()))using(var f=Host(p)){
  int uiThread=System.Threading.Thread.CurrentThread.ManagedThreadId,driverThread=uiThread;var reader=F<Func<PageSettings,PrinterPageGeometry>>(p,"geometryReader");Set(p,"geometryReader",(Func<PageSettings,PrinterPageGeometry>)(page=>{driverThread=System.Threading.Thread.CurrentThread.ManagedThreadId;entered.Set();if(!release.WaitOne(5000))throw new Exception("driver fixture release timeout");return reader(page);}));Call(p,"StartRequest",true,false,null);Pump(()=>entered.WaitOne(0));Check(driverThread!=uiThread,"native geometry reader runs away from UI thread");int beats=0;using(var timer=new Timer{Interval=15}){timer.Tick+=delegate{beats++;};timer.Start();var s=Stopwatch.StartNew();F<NumericUpDown>(p,"offsetX").Value=1;while(beats<2&&s.ElapsedMilliseconds<1000){Application.DoEvents();System.Threading.Thread.Sleep(1);}Check(beats>=2,"UI heartbeat continues while driver is blocked");timer.Stop();}Set(p,"geometryReader",reader);int builds=p.PreviewBuilds;release.Set();Pump(()=>p.PreviewBuilds>builds);Check(F<NumericUpDown>(p,"offsetX").Value==1&&F<PrintDiagnostics>(p,"printDiagnostics").X==1,"obsolete result cannot overwrite newer correction");entered.Reset();release.Reset();Set(p,"geometryReader",(Func<PageSettings,PrinterPageGeometry>)(page=>{entered.Set();if(!release.WaitOne(5000))throw new Exception("close fixture timeout");return reader(page);}));Call(p,"StartRequest",true,false,null);Pump(()=>entered.WaitOne(0));var cache=F<object>(p,"previewCache");int delivered=p.PreviewBuilds;f.Close();using(var finished=new System.Threading.ManualResetEvent(false)){var worker=typeof(PrintPanel).Assembly.GetType("EanEtikety.PrintWorker",true);worker.GetMethod("Queue",BindingFlags.Public|BindingFlags.Static).Invoke(null,new object[]{new object(),(Action)(()=>finished.Set())});release.Set();Pump(()=>finished.WaitOne(0));}Check(p.PreviewBuilds==delivered&&(int)cache.GetType().GetProperty("ImageCount").GetValue(cache,null)==0,"closing during driver work rejects late delivery and frees cached resources");
 }}
 [STAThread]static void Main(string[] args){dir=args[0];Directory.CreateDirectory(dir);try{Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Reuse();FreshSubmit();OwnedPlans();Ownership();CacheFailures();Responsiveness();File.WriteAllText(Path.Combine(dir,"passed.txt"),"PASS "+checks+" preview reuse, invalidation, fresh submit, exact raster, heartbeat and resource ownership checks; no physical print");}catch(Exception e){File.WriteAllText(Path.Combine(dir,"failed.txt"),e.ToString());Environment.ExitCode=1;}}
}
